<div class="head"><div><h1>Bill <?= e($b['billing_month']) ?></h1><p class="muted"><?= e($b['full_name']) ?> · Meter <?= e($b['meter_no']) ?> · <?= e($b['address']) ?></p></div><?= badge($b['status']) ?></div>
<?php if ($role === 'admin' && $b['status'] === 'Unpaid'): ?><form method="post" action="<?= url('bills/cancel') ?>" data-confirm="Cancel this bill? This is recorded in the audit log."><?= csrf_field() ?><input type="hidden" name="bill_id" value="<?= (int)$b['bill_id'] ?>"><button class="act del"><?= icon('x') ?>Cancel bill</button></form><br><?php endif; ?>
<?php if ($role === 'admin' && $b['status'] !== 'Cancelled'): ?><form method="post" action="<?= url('bills/due') ?>" class="filter" data-validate><?= csrf_field() ?><input type="hidden" name="bill_id" value="<?= (int)$b['bill_id'] ?>"><label for="dd">Due date</label><input id="dd" type="date" name="due_date" required value="<?= e($b['due_date']) ?>"><button class="act save"><?= icon('save') ?>Update due date</button></form><?php endif; ?>
<div class="grid2"><div class="panel"><h2>Bill breakdown</h2><table>
<tr><th>Previous reading</th><td><?= e($b['previous_reading']) ?></td></tr><tr><th>Current reading</th><td><?= e($b['current_reading']) ?></td></tr><tr><th>Units used</th><td><?= e($b['units_used']) ?></td></tr>
<tr><th>Unit rate</th><td><?= e(money($b['unit_rate'])) ?></td></tr><tr><th>Water charge</th><td><?= e(money($b['units_used'] * $b['unit_rate'])) ?></td></tr><tr><th>Fixed charge</th><td><?= e(money($b['fixed_charge'])) ?></td></tr><tr><th>Tax</th><td><?= e(money($b['tax_amount'])) ?></td></tr>
<tr><th>Total</th><td><b><?= e(money($b['total_amount'])) ?></b></td></tr><tr><th>Paid</th><td><?= e(money($b['amount_paid'])) ?></td></tr><tr><th>Balance</th><td><b><?= e(money($b['total_amount'] - $b['amount_paid'])) ?></b></td></tr><tr><th>Due date</th><td><?= e($b['due_date']) ?></td></tr></table></div>
<?php if ($role === 'customer' && in_array($b['status'], ['Unpaid', 'Partially Paid'], true)): ?><div class="panel"><h2>Pay this bill</h2><p class="muted">Pay by mobile money, bank transfer or card, then enter the transaction reference below. Our staff will confirm it and your balance will update.</p>
<form method="post" action="<?= url('payments/submit') ?>" data-validate><?= csrf_field() ?><input type="hidden" name="bill_id" value="<?= (int)$b['bill_id'] ?>"><label for="pa">Amount (RWF)</label><input id="pa" type="number" step="0.01" min="0.01" name="amount" required value="<?= e(round($b['total_amount'] - $b['amount_paid'], 2)) ?>">
<label for="pm">Method</label><select id="pm" name="method" required><?php foreach (['Mobile Money', 'Bank Transfer', 'Card'] as $m): ?><option><?= e($m) ?></option><?php endforeach; ?></select><label for="pr">Transaction reference</label><input id="pr" name="reference" required minlength="3" maxlength="60"><button class="btn">Submit payment</button></form></div><?php endif; ?>
<?php if ($role !== 'customer' && in_array($b['status'], ['Unpaid', 'Partially Paid'], true)): ?><div class="panel"><h2>Record payment</h2><form method="post" action="<?= url('bills/pay') ?>" data-validate><?= csrf_field() ?><input type="hidden" name="bill_id" value="<?= (int)$b['bill_id'] ?>">
<label for="am">Amount</label><input id="am" type="number" step="0.01" min="0.01" name="amount" required><label for="pd">Date</label><input id="pd" type="date" name="payment_date" required value="<?= date('Y-m-d') ?>" max="<?= date('Y-m-d') ?>">
<label for="me">Method</label><select id="me" name="method" required><?php foreach (['Cash', 'Mobile Money', 'Bank Transfer', 'Card'] as $m): ?><option><?= e($m) ?></option><?php endforeach; ?></select>
<label for="rf">Transaction reference</label><input id="rf" name="reference" maxlength="60"><button class="btn">Save payment</button></form></div><?php endif; ?></div>
<div class="panel"><h2>Payments</h2><div class="tw"><table><tr><th>Date</th><th>Amount</th><th>Method</th><th>Reference</th><th>Recorded by</th><th>Status</th><th></th></tr>
<?php foreach ($pays as $p): ?><tr><td><?= e($p['payment_date']) ?></td><td><?= e(money($p['amount_paid'])) ?></td><td><?= e($p['payment_method']) ?></td><td><?= e($p['transaction_reference']) ?></td><td><?= e($p['username']) ?></td><td><?= e($p['status']) ?></td>
<td><?php if ($role === 'admin' && $p['status'] === 'Completed'): ?><form method="post" action="<?= url('bills/voidpay') ?>" data-confirm="Void this payment?"><?= csrf_field() ?><input type="hidden" name="payment_id" value="<?= (int)$p['payment_id'] ?>"><input type="hidden" name="bill_id" value="<?= (int)$b['bill_id'] ?>"><button class="act warn"><?= icon('x') ?>Void</button></form><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$pays): ?><tr><td colspan="7" class="muted">No payments yet.</td></tr><?php endif; ?></table></div></div>
